import{_t as e,it as t,n,rt as r}from"./chunks/framework.Ke88N3OB.js";var i=JSON.parse(`{"title":"Testing","description":"Unit tests and integration tests against a real Pumpkin server","frontmatter":{"navigation":{"category":"Plugin development"},"title":"Testing","description":"Unit tests and integration tests against a real Pumpkin server","editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/docs/testing.md"},"headers":[],"relativePath":"guides/testing.md","filePath":"docs/testing.md","lastUpdated":1792259132000}`),a={name:`guides/testing.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="testing" tabindex="-1">Testing <a class="header-anchor" href="#testing" aria-label="Permalink to “Testing”">​</a></h1><p>Plugin packages use <code>definePluginVitestConfig()</code> from <code>@pumpkin-plugins/test-harness/vitest</code> to define two Vitest projects:</p><table tabindex="0"><thead><tr><th>Project</th><th>Files</th><th>Runs</th></tr></thead><tbody><tr><td><code>unit</code></td><td><code>src/**/*.test.ts</code></td><td><code>pnpm test</code>. No server needed.</td></tr><tr><td><code>integration</code></td><td><code>test/**/*.itest.ts</code></td><td><code>pnpm test:integration</code>. Builds first, then runs against a real Pumpkin. Test files and up to four package suites run concurrently.</td></tr></tbody></table><p>From the repository root, <code>pnpm coverage</code> runs workspace coverage suites, including the creator&#39;s CLI integration tests, then repository-script, agent-hook and GitHub Action tests. Vitest writes each package&#39;s <code>coverage/lcov.info</code>. An outer c8 collector also measures Node child processes, including documentation and build CLIs, and writes <code>coverage/process/lcov.info</code>. Codecov merges these reports so subprocess execution contributes alongside in-process tests. Coverage tasks run fresh because cached reports cannot supply their child processes&#39; raw V8 data.</p><p>The existing <code>codecov/project</code> gate covers tooling: <code>tools/</code>, <code>scripts/</code>, <code>actions/</code> and <code>.agents/hooks/</code>. It compares against the base commit with a 1 percentage-point tolerance. CI runs the complete coverage job for action-only changes too, so a partial action-matrix upload cannot stand in for the full tooling report. The separate <code>guest</code> status covers <code>packages/</code> and is informational: its Node coverage does not measure plugin execution inside WASM. Shared libraries under <code>tools/</code> remain in the tooling gate; their coverage describes measured Node execution, not their execution inside a server.</p><p>Unexecuted source remains in both collectors&#39; denominators. The process collector covers the host-side source and CLI directories; it excludes test/spec files, declarations, test fixtures, snapshots and downloaded third-party caches. It does not pretend that Node instrumentation measures compiled WASM. Add tests for uncovered failure scenarios, rather than to raise the reported percentage.</p><p>Open <code>coverage/process/index.html</code> to inspect process coverage. <code>coverage/process/run.json</code> records the revision, Node version, repeat command, command exit statuses and report SHA-256 hashes. CI retains these reports and regression evidence in the <code>coverage-evidence</code> artifact, including on failure. Keep scenario inputs and observable outputs with new E2E evidence so another person can repeat and verify it.</p><p>The coverage collector&#39;s regression scenario checks failures that ordinary behavior suites cannot detect: lost child-process hits, dropped unexecuted TypeScript, stale hits from an earlier run, third-party caches counted as repository source and swallowed nonzero process exits. Run it with <code>pnpm exec node --test scripts/coverage.test.mjs</code>; its evidence is written to <code>coverage/verification/process-coverage/</code>.</p><p>To run one plugin&#39;s integration tests, replace <code>my-plugin</code> with the package&#39;s folder name:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> turbo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:integration</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter=@pumpkin-plugins/my-plugin</span></span></code></pre></div><p>To run only changed packages and their dependents, compare them with the base branch. For example: <code>pnpm turbo run test:integration --filter=&#39;...[origin/master]&#39;</code>.</p><p>CI selects real-server suites for changed plugins and the workspace packages their build or integration tests depend on, along with those packages&#39; dependents. Changes to workspace-wide build configuration or shared integration setup run every suite. Unrelated script and workflow changes skip the integration job.</p><h2 id="integration-tests" tabindex="-1">Integration tests <a class="header-anchor" href="#integration-tests" aria-label="Permalink to “Integration tests”">​</a></h2><p><code>@pumpkin-plugins/test-harness</code> starts a real server for each test file. It uses a temporary directory and free ports, and turns off plugin permission prompts and telemetry. The harness sets <code>RUST_LOG=info</code> for Pumpkin so readiness checks and assertions can see startup and plugin INFO logs, even if your shell uses a stricter log filter:</p><div class="language-ts"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">// packages/&lt;folder&gt;/test/my.itest.ts</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { builtPluginPath, startPumpkin } </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@pumpkin-plugins/test-harness&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> server</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> startPumpkin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    plugins: [</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">builtPluginPath</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(process.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cwd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">())],</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    files: { </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;plugins/data/MyPlugin/config.toml&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;...&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }, </span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">// seed files before start</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    config: {</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">        /* overrides merged into pumpkin.toml */</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> server.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">waitForLog</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/</span><span style="--shiki-light:#032F62;--shiki-dark:#DBEDFF;">Loaded MyPlugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">server.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">command</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;list&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> server.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">stop</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Member</th><th></th></tr></thead><tbody><tr><td><code>server.javaPort</code>, <code>server.bedrockPort</code></td><td>The free ports the server listens on</td></tr><tr><td><code>server.logs()</code>, <code>server.lines</code></td><td>Server output with color codes removed</td></tr><tr><td><code>server.errors()</code></td><td><code>ERROR</code> lines except the harness&#39;s baseline errors (<a href="https://github.com/filiphsps/pumpkin-plugins/blob/master/tools/test-harness/src/instance.ts" target="_blank" rel="noreferrer">defined in <code>instance.ts</code></a>)</td></tr><tr><td><code>server.waitForLog(pattern, timeoutMs?, fromIndex?)</code></td><td>Resolves with the first matching line</td></tr><tr><td><code>server.command(text)</code></td><td>Runs a console command</td></tr><tr><td><code>server.pluginDataDir(name)</code></td><td>Path of <code>plugins/data/&lt;name&gt;/</code></td></tr><tr><td><code>server.stop()</code></td><td>Stops the server and removes its directory</td></tr></tbody></table><p>If a test run crashes, the harness kills its servers on exit so they don&#39;t keep holding ports. Each test file owns its server instances and temporary directories, which lets Vitest run files in parallel. The root command runs up to four package suites at once to reduce startup time without starting all package servers together. On hosted runners, CI limits this to two package suites at a time and reuses the WASM files from its build job, so the integration job doesn&#39;t build plugins again.</p><p>The harness chooses ports from 20000 to 30000, below the common default ephemeral-port ranges, which start at 32768 on Linux and 49152 on macOS and Windows. Operating systems can reconfigure those ranges, so they may still allocate a port from this range. Before returning a port, the harness checks that TCP and UDP loopback binds are available and avoids handing out the same port twice within its process. Another process could still claim a port before Pumpkin binds it. If startup reports <code>Address already in use</code>, the harness tries up to three starts in total, choosing new ports each time.</p><h2 id="packed-standalone-consumer" tabindex="-1">Packed standalone consumer <a class="header-anchor" href="#packed-standalone-consumer" aria-label="Permalink to “Packed standalone consumer”">​</a></h2><p>Run <code>pnpm run test:external-consumer</code> with the Node, pnpm, and host-tool versions listed in the <a href="/pumpkin-plugins/tools/static-hermes-runtime/README">Static Hermes Runtime guide</a>. This check packs the internal production dependencies and installs them from a temporary local registry. It then runs the packed creator binary and both real <code>pnpm create pumpkin-plugin</code> language flows, and typechecks and builds both starter projects. By default, the check uses a temporary pnpm store and Static Hermes cache outside the consumer project, then removes the temporary project when it finishes. To keep caches between runs, set <code>PUMPKIN_EXTERNAL_CONSUMER_PNPM_STORE_DIR</code> and <code>STATIC_HERMES_CACHE_DIR</code>. CI saves and restores both in the <a href="https://github.com/filiphsps/pumpkin-plugins/blob/master/.github/workflows/external-consumer.yml" target="_blank" rel="noreferrer">external-consumer workflow</a>.</p><p>The check also installs only the packed builder&#39;s production dependencies with pnpm hoisting disabled, then runs its CLI without an ambient TypeScript installation. To check that packaging boundary without compiling the starter projects, run <code>pnpm run test:external-consumer --build-cli-only</code>.</p><h2 id="the-server-binary" tabindex="-1">The server binary <a class="header-anchor" href="#the-server-binary" aria-label="Permalink to “The server binary”">​</a></h2><p>The release is pinned in <a href="https://github.com/filiphsps/pumpkin-plugins/blob/master/tools/test-harness/src/pumpkin-version.ts" target="_blank" rel="noreferrer"><code>pumpkin-version.ts</code></a>. Its plugin ABI should match the WIT ABI carried by <code>@pumpkin-plugins/pumpkin-api</code> in <code>pnpm-workspace.yaml</code>. The harness chooses the server binary in this order:</p><ol><li><code>PUMPKIN_BIN</code>, if set.</li><li>If <code>PUMPKIN_BIN</code> isn&#39;t set, the pinned release, downloaded once into <code>.cache/pumpkin</code> and checked against the release&#39;s <code>checksums.sha256</code>.</li></ol><table tabindex="0"><thead><tr><th>Variable</th><th>Effect</th></tr></thead><tbody><tr><td><code>PUMPKIN_BIN</code></td><td>Use this binary instead of downloading</td></tr><tr><td><code>PUMPKIN_CACHE_DIR</code></td><td>Where downloaded binaries are cached</td></tr><tr><td><code>PUMPKIN_KEEP_DIR=1</code></td><td>Keep each test server directory for inspection</td></tr><tr><td><code>PUMPKIN_TEST_LOG_DIR</code></td><td>Save each test server&#39;s full log here</td></tr></tbody></table>`,25)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};